class Solution {
public:
    vector<int> maxGeneticDifference(vector<int>& parents, vector<vector<int>>& queries) {
        int n = parents.size(), m = queries.size();
        vector<int> head(n, -1), nxt(n);
        int root = -1;
        for (int i = 0; i < n; i++) {
            if (parents[i] == -1) root = i;
            else { nxt[i] = head[parents[i]]; head[parents[i]] = i; }
        }
        vector<int> qhead(n, -1), qnxt(m);
        for (int i = 0; i < m; i++) {
            qnxt[i] = qhead[queries[i][0]];
            qhead[queries[i][0]] = i;
        }
        const int B = 17;
        vector<array<int,2>> ch(1, array<int,2>{0, 0});
        vector<int> cnt(1, 0);
        ch.reserve((size_t)(n + 1) * (B + 2));
        cnt.reserve((size_t)(n + 1) * (B + 2));

        auto insert = [&](int prev, int v) -> int {
            int cur = ch.size();
            array<int,2> prevCh = ch[prev];
            int prevCnt = cnt[prev];
            ch.push_back(prevCh);
            cnt.push_back(prevCnt + 1);
            int newRoot = cur;
            for (int b = B; b >= 0; b--) {
                int bit = (v >> b) & 1;
                int old = ch[prev][bit];
                int nn = ch.size();
                if (old) {
                    array<int,2> oldCh = ch[old];
                    int oldCnt = cnt[old];
                    ch.push_back(oldCh);
                    cnt.push_back(oldCnt + 1);
                } else {
                    ch.push_back(array<int,2>{0, 0});
                    cnt.push_back(1);
                }
                ch[cur][bit] = nn;
                prev = old;
                cur = nn;
            }
            return newRoot;
        };

        auto query = [&](int ver, int v) -> int {
            int res = 0, cur = ver;
            for (int b = B; b >= 0; b--) {
                int bit = (v >> b) & 1;
                int want = ch[cur][bit ^ 1];
                if (want && cnt[want] > 0) { res |= 1 << b; cur = want; }
                else cur = ch[cur][bit];
            }
            return res;
        };

        vector<int> ans(m, 0);
        vector<pair<int,int>> st;
        st.reserve(n);
        st.push_back({root, 0});
        while (!st.empty()) {
            auto [u, pv] = st.back();
            st.pop_back();
            int v = insert(pv, u);
            for (int qi = qhead[u]; qi != -1; qi = qnxt[qi])
                ans[qi] = query(v, queries[qi][1]);
            for (int c = head[u]; c != -1; c = nxt[c])
                st.push_back({c, v});
        }
        return ans;
    }
};
